SELECT eo.id, eo.no, eo.user_id AS userId, u.nickname AS userName, eo.category_id AS categoryId, ec.name AS categoryName, eo.goods_id AS goodsId, eo.goods_name AS goodsName, eo.cost_point AS costPoint, eo.pay_status AS payStatus, eo.pay_time AS payTime, eo.ship_time AS shipTime, eo.logistics_info AS logisticsInfo, eo.archive_time AS archiveTime, eo.reserve1, eo.reserve2, eo.creator, eo.create_time AS createTime, eo.update_time AS updateTime FROM exchange_order eo LEFT JOIN user_info u ON eo.user_id = u.id AND u.deleted = 0 LEFT JOIN exchange_category ec ON eo.category_id = ec.id AND ec.deleted = 0 WHERE eo.deleted = 0
AND eo.no LIKE CONCAT('%', #{reqVO.no}, '%')
AND eo.category_id = #{reqVO.categoryId}
AND eo.goods_id = #{reqVO.goodsId}
AND eo.user_id = #{reqVO.userId}
AND eo.pay_status = #{reqVO.payStatus}
AND eo.create_time BETWEEN DATE(#{reqVO.date}) AND DATE(DATE_ADD(#{reqVO.date}, INTERVAL 1 DAY))
AND eo.create_time BETWEEN DATE(FROM_UNIXTIME(#{reqVO.startTime} / 1000)) AND DATE(FROM_UNIXTIME(#{reqVO.endTime} / 1000))
AND eo.create_time >= DATE(FROM_UNIXTIME(#{reqVO.startTime} / 1000))
AND eo.create_time <= DATE(FROM_UNIXTIME(#{reqVO.endTime} / 1000))
ORDER BY eo.id DESC

SELECT eo.id, eo.no, eo.user_id AS userId, u.nickname AS userName, eo.category_id AS categoryId, ec.name AS categoryName, eo.goods_id AS goodsId, eo.goods_name AS goodsName, eo.cost_point AS costPoint, eo.pay_status AS payStatus, eo.pay_time AS payTime, eo.ship_time AS shipTime, eo.logistics_info AS logisticsInfo, eo.archive_time AS archiveTime, eo.reserve1, eo.reserve2, eo.creator, eo.create_time AS createTime, eo.update_time AS updateTime FROM exchange_order eo LEFT JOIN user_info u ON eo.user_id = u.id AND u.deleted = 0 LEFT JOIN exchange_category ec ON eo.category_id = ec.id AND ec.deleted = 0 WHERE eo.deleted = 0 AND eo.id IN
#{id}
ORDER BY eo.id DESC
